<template>
<app-layout :umi-section="true">
  <Head :title="$t(&quot;我的 UMI · Deepro&quot;)" />
  <main class="uf-page">
    <header class="uf-head">
      <button v-if="secondaryPage" class="uf-back" @click="selectTab('mine')">‹ {{ $t('返回') }}</button><Link v-else href="/" class="uf-back">‹ Deepro</Link>
      <h1><img src="/umi/v2/art/umi-token.png" alt="">{{ pageTitle }}</h1>
      <button v-if="tab!=='mine' && data.member" @click="selectTab('mine')">{{ $t('我的') }}</button><span v-else-if="data.member">V{{data.member.level}}</span><span v-else>UMI</span>
    </header>
    <section v-if="tab==='home'" class="uf-intro">
      <small>UMI ECOSYSTEM</small><h2>{{ $t('UMI 生态') }}<br>{{ $t('管理我的资产') }}</h2><p>UMI · Deepro</p>
      <img src="/umi/v2/art/coin-stacks.png" alt=""><button @click="data.member?selectTab('join'):$refs.enroll?.scrollIntoView({behavior:'smooth'})">{{ $t('充值 UMI') }} ↗</button>
    </section>
    <div v-if="(tab==='join' && !data.operations?.intake) || (['withdraw','transfer'].includes(tab) && !data.operations?.withdrawal)" class="uf-notice">{{ $t(tab==='join'?(data.ready?'UMI 充值已暂停':'UMI 充值筹备中，开放后可从现货账户划入。'):(data.ready?'UMI 提取已暂停':'UMI 提取筹备中')) }}</div>
    <section v-if="!data.member" class="uf-card uf-enroll" ref="enroll"><h2>{{ $t("开通 UMI 账户") }}</h2><p v-if="data.historical_activation">{{ $t("已找到原 UMI 账户") }}</p><p v-else>{{ $t("请输入 UMI 邀请码") }}</p><label v-if="!data.historical_activation">{{ $t("UMI 邀请码") }}<input :disabled="busy" v-model.trim="sponsorCode" maxlength="40" required :placeholder="$t(&quot;请输入 UMI 专属邀请码&quot;)"></label><button :disabled="busy || !data.enrollment_enabled || (!data.historical_activation && !sponsorCode)" @click="submit('enroll')">{{ $t("开通账户") }}</button></section>
    <section v-if="!data.member && !legacy" class="uf-card uf-enroll" ref="enroll"><h2>{{ $t("接入原 UMI 账户") }}</h2><label v-if="!legacyChallenge">{{ $t("原 UID 或账号") }}<input :disabled="busy" v-model.trim="legacyIdentifier" maxlength="255" :placeholder="$t(&quot;请输入原 UID 或账号&quot;)"></label><label v-else>{{ $t("8 位邮箱验证码") }}<input :disabled="busy" v-model.trim="legacyCode" inputmode="numeric" maxlength="8" :placeholder="$t(&quot;请输入验证码&quot;)"></label><button :disabled="busy || (!legacyChallenge && !legacyIdentifier) || (legacyChallenge && legacyCode.length!==8)" @click="legacyChallenge?completeLegacyBinding():startLegacyBinding()">{{legacyChallenge?$t('验证并接入'):$t('获取验证码')}}</button><p v-if="legacyChallenge">{{ $t("验证码发送至原账户核定邮箱，10 分钟内有效。") }}</p><a href="/umi-ecosystem/activate">{{ $t("尚未设置 Deepro 登录密码？激活原账户 ›") }}</a></section>
    <template v-if="data.member">
      <section v-if="tab==='mine'" class="uf-hero">
        <button class="uf-card-record" @click="selectTab('progress')">{{ $t('记录') }}</button>
        <small>{{ $t('可提现收益') }}</small><strong>{{ fmt(income.available) }} <em>UMI</em></strong>
        <span>Deepro {{ $t('现货') }} · {{data.wallet_available?fmt(data.wallet_umi):'—'}} UMI</span>
      </section>
      <section v-if="tab==='home'" class="uf-home">
        <div class="uf-home-actions"><button @click="selectTab('mine')"><span>▱</span>{{ $t('我的资产') }}</button><button @click="selectTab('income')"><span>↗</span>{{ $t('我的收益') }}</button><button @click="selectTab('team')"><span>♧</span>{{ $t('我的团队') }}</button></div>
        <article class="uf-card"><Link :href="handoff('/market/UMI-USDT')" class="uf-row"><span>{{ $t('UMI 价格') }}</span><b>{{data.spot_quote?.available?fmt(data.spot_quote.quote.price):$t('更新中')}} USDT</b></Link><button class="uf-row uf-row-button" @click="selectTab('burn')"><span>{{ $t('累计已销毁') }}</span><b>{{fmt(data.burn.confirmed_umi)}} UMI ›</b></button><div class="uf-row"><span>{{ $t('过去 24 小时') }}</span><b>{{fmt(data.burn.past_24h_umi)}} UMI</b></div></article>
        <div class="uf-metrics"><article><small>{{ $t('剩余额度') }} · UMI</small><strong>{{fmt(data.cycle_summary.active_remaining_umi)}}</strong></article><article><small>{{ $t('累计已释放') }} · UMI</small><strong>{{fmt(data.cycle_summary.total_released_umi)}}</strong></article></div>
        <article class="uf-card"><button class="uf-link" @click="selectTab('points')">{{ $t('股票积分') }} <span>›</span></button><button class="uf-link" @click="selectTab('records')">{{ $t('账务记录') }} <span>›</span></button></article>
      </section>
      <section v-if="tab==='join'" class="uf-grid"><article class="uf-card"><h2>{{ $t("充值 UMI") }}</h2><p style="margin:8px 0 16px;font-size:13px">{{ $t("从 Deepro 现货账户划入 UMI") }}</p><div class="uf-tier-table"><div v-for="tier in data.participation_tiers" :key="tier.minimum_usdt"><span>{{fmt(tier.minimum_usdt)}} {{tier.maximum_exclusive_usdt?'≤ USDT < '+fmt(tier.maximum_exclusive_usdt):'USDT +'}}</span><b>{{tier.multiple}} {{ $t('倍额度') }}</b></div></div><div class="uf-row"><span>{{ $t('现货可用') }}</span><b>{{fmt(data.wallet_umi)}} UMI</b></div><p v-if="positive(data.pending_principal_umi)">{{ $t("待激活本金") }} {{fmt(data.pending_principal_umi)}} {{ $t("UMI，补足至 100 USDT 后开始计算收益。") }}</p><label>{{ $t("充值数量 · UMI") }}<input :disabled="busy" v-model.trim="joinAmount" inputmode="decimal" :placeholder="$t(&quot;请输入数量&quot;)" @input="joinPreview=null"></label><button class="uf-outline" :disabled="!data.operations?.intake || busy" @click="preview('activate',joinAmount,'joinPreview')">{{ $t("预览") }}</button><div v-if="joinPreview" class="uf-preview"><div><span>{{ $t("盘口卖一价") }}</span><b>{{fmt(joinPreview.quote)}} USDT</b></div><p>{{ $t("报价时间") }} {{date(joinPreview.quote_at)}}{{ $t("；提交时按最新卖一价计价。") }}</p><div><span>{{ $t("充值价值") }}</span><b>{{ fmt(joinPreview.principal_usd) }} USDT</b></div><div><span>{{ $t("释放倍数") }}</span><b>{{ joinPreview.multiplier }} {{ $t("倍") }}</b></div><div><span>{{ $t("本轮额度") }}</span><b>{{ fmt(joinPreview.cap_umi) }} UMI</b></div></div><div class="uf-actions"><button :disabled="!data.operations?.intake || !data.wallet_available || !joinPreview || busy" @click="submit('activate',{amount:joinAmount})">{{ $t("确认充值") }}</button></div><a :href="handoff('/market/UMI-USDT')">{{ $t("查看 UMI/USDT 现货市场 ›") }}</a></article><article class="uf-card"><h2>{{ $t("充值记录") }}</h2><a :href="recordUrl('intents')">{{ $t("查询全部记录与导出 ›") }}</a><p v-if="!data.cycles.length" class="uf-empty">{{ $t("暂无充值记录") }}</p><div v-for="c in data.cycles" :key="c.id" class="uf-record"><div><b>{{ $t("第") }} {{ c.cycle_number }} {{ $t("轮 ·") }} {{ c.multiplier }} {{ $t("倍") }}</b><span>{{ $t(cycleStatus(c.status)) }}</span></div><small>{{ $t("总额度") }} {{ fmt(c.cap_umi) }} {{ $t("· 已释放") }} {{ fmt(c.released_umi) }} UMI</small></div><div v-for="i in data.intents.filter(x=>x.status==='awaiting_credit')" :key="'i'+i.id" class="uf-record"><b>{{ $t("等待充值") }} {{ fmt(i.amount_umi) }} UMI</b><small>{{ $t("历史待处理订单，请联系运营核对") }}</small></div></article></section>
      <section v-if="tab==='transfer'" class="uf-grid"><article class="uf-card"><h2>{{ $t("收益划转") }}</h2><label>{{ $t("充值轮次") }}<select :disabled="busy" v-model="transferCycle"><option value="">{{ $t("请选择轮次") }}</option><option v-for="c in transferableCycles" :key="c.id" :value="c.id">{{ $t("第") }} {{ c.cycle_number }} {{ $t("轮 · 可转") }} {{fmt(c.transferable[transferPocket])}} UMI</option></select></label><label>{{ $t("收益类别") }}<select :disabled="busy" v-model="transferPocket"><option value="static">{{ $t("理财收益") }}</option><option value="team">{{ $t("团队收益") }}</option><option value="referral">{{ $t("推荐收益") }}</option></select></label><p>{{ $t("本轮此类可划转") }} {{fmt(transferMaximum)}} UMI</p><button class="uf-outline" :disabled="busy || !transferCycle" @click="transferAmount=transferMaximum">{{ $t("使用本轮可转数量") }}</button><label>{{ $t("划转数量 · UMI") }}<input :disabled="busy" v-model.trim="transferAmount" inputmode="decimal" :placeholder="$t(&quot;请输入数量&quot;)"></label><button :disabled="!data.operations?.withdrawal || !transferCycle || !validTransfer || busy" @click="submit('transfer',{cycle_id:transferCycle,pocket:transferPocket,amount:transferAmount})">{{ $t("确认划转") }}</button></article><article class="uf-card"><h2>{{ $t("近期释放明细") }}</h2><a :href="recordUrl('releases')">{{ $t("查询全部记录与导出 ›") }}</a><p v-if="!data.releases.length" class="uf-empty">{{ $t("暂无释放明细") }}</p><div v-for="r in data.releases" :key="r.id" class="uf-record"><div><b>{{ $t(pocket(r.kind)) }}</b><span>+{{ fmt(r.released_umi) }}</span></div><small>{{ r.business_date }}</small></div></article></section>
      <section v-if="tab==='withdraw'" class="uf-grid"><article class="uf-card"><h2>{{ $t("提取到 Deepro") }}</h2><p>{{ $t('到账至 Deepro 资金账户，另需 30% UMI 销毁。') }}</p><label>{{ $t("到账数量 · UMI") }}<input :disabled="busy" v-model.trim="withdrawAmount" inputmode="decimal" :placeholder="$t(&quot;请输入数量&quot;)" @input="withdrawPreview=null"></label><button class="uf-outline" :disabled="!data.operations?.withdrawal || busy" @click="preview('withdraw',withdrawAmount,'withdrawPreview')">{{ $t("计算所需 UMI") }}</button><div v-if="withdrawPreview" class="uf-preview"><div><span>{{ $t("到账") }}</span><b>{{ fmt(withdrawPreview.pay_to_user_umi) }} UMI</b></div><div><span>{{ $t("额外准备") }}</span><b>{{ fmt(withdrawPreview.extra_b_umi) }} UMI</b></div><div><span>{{ $t("其中使用剩余收益") }}</span><b>{{fmt(withdrawPreview.from_income_umi)}} UMI</b></div><div><span>{{ $t("其中使用现货余额") }}</span><b>{{fmt(withdrawPreview.from_wallet_umi)}} UMI</b></div><div><span>{{ $t("还需从现货划入") }}</span><b>{{ fmt(withdrawPreview.external_shortfall_umi) }} UMI</b></div><div><span>{{ $t("可提收益变化") }}</span><b>{{fmt(withdrawPreview.income_before_umi)}} → {{fmt(withdrawPreview.income_after_umi)}} UMI</b></div><div><span>{{ $t("现货划出后余额") }}</span><b>{{fmt(withdrawPreview.wallet_before_umi)}} → {{fmt(withdrawPreview.wallet_after_funding_umi)}} UMI</b></div></div><button :disabled="!data.operations?.withdrawal || !withdrawPreview || busy" @click="submit('withdraw',{amount:withdrawAmount})">{{ $t("确认提取到 Deepro") }}</button><button class="uf-link" @click="selectTab('progress')">{{ $t('提取进度') }} <span>›</span></button></article></section><section v-if="tab==='progress'" class="uf-grid"><article class="uf-card"><h2>{{ $t("近期提现记录") }}</h2><a :href="recordUrl('withdrawals')">{{ $t("查询全部记录与导出 ›") }}</a><p v-if="!data.withdrawals.length" class="uf-empty">{{ $t("暂无提现记录") }}</p><div v-for="w in data.withdrawals" :key="w.id" class="uf-record"><div><b>{{ fmt(w.requested_umi) }} UMI</b><span>{{ $t(withdrawStatus(w.status)) }}</span></div><small>{{ $t("订单 #") }}{{w.id}} · {{date(w.created_at)}}</small><small>{{ $t("额外准备") }} {{fmt(w.required_burn_umi)}} {{ $t("· 已到 Deepro") }} {{fmt(w.paid_umi)}} UMI</small><small>{{ $t("销毁已确认") }} {{fmt(w.confirmed_burn_umi)}} UMI</small><small>{{ $t("资金来源：收益") }} {{fmt(w.from_income_umi)}} {{ $t("/ 账户划入") }} {{fmt(w.from_wallet_umi)}} {{ $t("/ 历史充值") }} {{fmt(w.from_deposit_umi)}} UMI</small><small v-if="w.paid_at">{{ $t("到账时间") }} {{date(w.paid_at)}} {{ $t("· 凭证") }} {{w.payout_ref}}</small><details class="uf-timeline"><summary>{{ $t("查看到账、销毁与权益进度") }}</summary><ol><li>{{ $t("已受理 ·") }} {{date(w.created_at)}}</li><li>{{positive(w.remaining_umi)?$t('等待补款 ')+fmt(w.remaining_umi)+' UMI':$t('销毁资金已齐备')}}</li><li>{{w.paid_at?$t('已到 Deepro · ')+date(w.paid_at):$t('尚未到账')}}</li><li v-for="l in w.burn_records" :key="'lot'+l.id">{{ $t("销毁任务 #") }}{{l.id}} · {{ $t(statusLabel(l.status)) }} · {{fmt(l.amount_umi)}} UMI<small>{{date(l.confirmed_at||l.created_at)}}</small><a v-if="Number(l.chain_id)===56 && /^0x[a-fA-F0-9]{64}$/.test(l.tx_hash||'')" :href="'https://bscscan.com/tx/'+l.tx_hash" target="_blank" rel="noopener noreferrer">{{ $t("查看链上凭证") }}</a></li><li v-if="!w.burn_records.length">{{ $t("尚未生成销毁任务") }}</li><li v-for="p in w.point_records" :key="'point'+p.id">{{ $t("积分 #") }}{{p.id}} · {{fmt(p.delta_points)}} · {{ $t(stockStatus(p.term_status)) }}<small>{{ $t("获得") }} {{date(p.created_at)}}</small><small>{{ $t("确权：") }}{{p.confirmed_at?date(p.confirmed_at):$t('预计 ')+date(p.eligible_at)}}</small><small>{{ $t("解锁：") }}{{p.tradable_at?date(p.tradable_at):$t('预计 ')+date(p.unlock_at)}}</small></li><li v-if="!w.point_records.length">{{ $t("积分尚未记入，等待销毁与报价核验。") }}</li></ol><a :href="recordUrl('lots',w.id)">{{ $t("本单销毁凭证 ›") }}</a> · <a :href="recordUrl('points',w.id)">{{ $t("本单积分记录 ›") }}</a></details><template v-if="positive(w.remaining_umi)"><small>{{ $t("还需从现货划入") }} {{ fmt(w.remaining_umi) }} UMI</small><button :disabled="busy || !data.operations?.withdrawal || !data.wallet_available" @click="submit('spot_topup',{withdrawal_id:w.id})">{{ $t("从现货划入补足") }}</button></template></div><a :href="handoff('/market/UMI-USDT')">{{ $t("前往 UMI 现货交易 ›") }}</a></article></section>
      <template v-if="tab==='team'"><section class="uf-card uf-team-identity"><div class="uf-row"><b>{{ data.member.member_code }}</b><span>V{{ data.member.level }}</span></div><div class="uf-invite-line"><span>{{ $t('我的邀请码') }} <strong>{{data.member.member_code}}</strong></span><button @click="copyInvite(data.member.member_code)">{{ $t('复制') }}</button></div><details><summary>{{ $t('邀请好友') }}</summary><div class="uf-invite-qr"><qr-code :size="144" :text="inviteUrl"/></div><input :value="inviteUrl" readonly @focus="$event.target.select()"><button @click="copyInvite(inviteUrl)">{{ $t('复制邀请链接') }}</button></details></section><umi-team-overview :income-summary="data.income_summary"/></template>
      <umi-income :quota="data.cycle_summary" v-if="tab==='income'" :summary="data.income_summary || {}" :initial-kind="incomeKind" @transfer="openIncomeTransfer"/>
      <section v-if="tab==='burn'" class="uf-grid"><article class="uf-card"><h2>{{ $t("销毁数据") }}</h2><div class="uf-row"><span>{{ $t("累计已销毁") }}</span><b>{{ fmt(data.burn.confirmed_umi) }} UMI</b></div><div class="uf-row"><span>{{ $t("过去 24 小时") }}</span><b>{{ fmt(data.burn.past_24h_umi) }} UMI</b></div><div class="uf-row"><span>{{ $t("等待链上确认") }}</span><b>{{ fmt(data.burn.pending_umi) }} UMI</b></div><p>{{ $t("仅将已在链上确认的 UMI 计入已销毁。") }}</p></article><article class="uf-card"><h2>{{ $t("近期销毁记录") }}</h2><a :href="recordUrl('lots')">{{ $t("查询全部记录与导出 ›") }}</a><p v-if="!data.lots.length" class="uf-empty">{{ $t("暂无记录") }}</p><div v-for="l in data.lots" :key="l.id" class="uf-record"><div><b>{{ $t(burnPurpose(l.purpose)) }} · {{ fmt(l.amount_umi) }} UMI</b><span>{{ l.status==='confirmed'?$t('已销毁'):$t('处理中') }}</span></div><small>{{date(l.confirmed_at || l.created_at)}}</small></div></article></section>
      <section v-if="tab==='points'" class="uf-grid"><article class="uf-card"><h2>{{ $t("盈证国际 · 参考份额权益") }}</h2><details><summary>{{ $t("产品说明") }}</summary><p>{{ $t("本产品为站内价格参考份额，不代表上市公司股东登记或外部证券持仓。") }}</p></details><details><summary>{{ $t('解锁规则') }}</summary><p>{{ $t('积分满 60 天确权，确权后锁定 90 天，以处理记录为准。') }}</p></details><div class="uf-row"><span>{{ $t("股票积分余额") }}</span><b>{{ fmt(pointBalance) }}</b></div><div class="uf-row"><span>{{ $t("UMI 参考份额余额") }}</span><b>{{fmt(stockBalance)}} {{ $t("份") }}</b></div><div class="uf-row"><span>{{ $t("其中锁定") }}</span><b>{{ fmt(data.stock_account?.locked_shares) }} {{ $t("份") }}</b></div><div class="uf-row"><span>{{ $t("可划转份额") }}</span><b>{{ fmt(data.stock_account?.available_shares) }} {{ $t("份") }}</b></div><div class="uf-row"><span>{{ $t("Deepro HK08379 交易账户") }}</span><b>{{ fmt(data.stock_trading_wallet?.balance) }} {{ $t("份额") }}</b></div><p>{{ $t("解锁后可划转至 Deepro 现货账户，在港股开市时交易。") }}</p><label>{{ $t("划转数量") }}<input :disabled="busy" v-model.trim="stockAmount" inputmode="decimal" :placeholder="$t(&quot;请输入已解锁份额&quot;)" @input="stockConfirm=false"></label><div class="uf-actions"><button class="uf-outline" :disabled="busy || !data.stock_trading_wallet?.enabled" @click="stockAmount=data.stock_trading_wallet.maximum;stockConfirm=false">{{ $t("最大可转") }} {{ fmt(data.stock_trading_wallet?.maximum) }}</button><button :disabled="busy || !data.stock_trading_wallet?.enabled || !validStockAmount" @click="stockConfirm=true">{{ $t("转入交易账户") }}</button></div><div v-if="stockConfirm" class="uf-preview" role="region" :aria-label="$t(&quot;确认股票划转&quot;)"><p>{{ $t("将") }} {{ fmt(stockAmount) }} {{ $t("份额转入您的 Deepro HK08379 交易账户。") }}</p><p>{{ $t("划转完成后，可在港股开市时交易。") }}</p><div class="uf-actions"><button :disabled="busy || !validStockAmount" @click="submit('stock_to_deepro',{amount:stockAmount})">{{ $t("确认划转") }}</button><button class="uf-outline" :disabled="busy" @click="stockConfirm=false">{{ $t("取消") }}</button></div></div><p v-if="!data.stock_trading_wallet?.enabled">{{data.stock_trading_wallet?.reason || $t('股票划转暂未开放。')}}</p><a v-else class="uf-link" :href="handoff('/market/HK08379-USDT')">{{ $t("查看盈证国际交易页") }} <span>›</span></a></article><article class="uf-card"><h2>{{ $t("近期权益明细") }}</h2><a :href="recordUrl('points')">{{ $t("查询全部记录与导出 ›") }}</a><p v-if="!data.points.length" class="uf-empty">{{ $t("暂无记录") }}</p><div v-for="p in data.points" :key="p.id" class="uf-record"><div><b>{{ fmt(p.delta_points) }} {{ $t("积分") }}</b><span>{{ $t(stockStatus(p.term_status)) }}</span></div><small>{{ $t("提现 #") }}{{ p.withdrawal_id }} · {{ date(p.created_at) }}</small><small v-if="p.eligible_at">{{ $t("预计确权") }} {{ date(p.eligible_at) }}</small><small v-if="p.unlock_at">{{ $t("预计可划转") }} {{ date(p.unlock_at) }}</small><small v-if="p.confirmed_at">{{ $t("已确权") }} {{ date(p.confirmed_at) }}</small><small v-if="p.tradable_at">{{ $t("已解锁") }} {{ date(p.tradable_at) }}</small></div></article><article class="uf-card"><h2>{{ $t("近期份额流水") }}</h2><a :href="recordUrl('stock_moves')">{{ $t("查询全部记录与导出 ›") }}</a><p v-if="!data.stock_moves?.length" class="uf-empty">{{ $t("暂无划转记录") }}</p><div v-for="m in data.stock_moves" :key="m.id" class="uf-record"><div><b>{{ $t(stockMove(m.kind)) }} · {{ fmt(m.shares) }} {{ $t("份") }}</b><span>{{ date(m.created_at) }}</span></div><small v-if="m.from_member_id && m.to_member_id && m.from_member_id!==m.to_member_id">{{ $t("成员") }} {{ m.from_member_id }} → {{ m.to_member_id }}</small></div></article></section>
    </template>
      <section v-if="tab==='history'" class="uf-grid">
        <article v-if="!legacy && !businessHistory" class="uf-card"><h2>{{ $t("账户资料") }}</h2><p>{{ $t("当前 Deepro 账户尚无已接入的原 UMI 档案。原用户可以在开通前验证并接入原账户。") }}</p><a href="/umi-ecosystem/activate">{{ $t("查看原用户激活 ›") }}</a></article>
        <template v-if="legacy">
          <article class="uf-card"><h2>{{ $t("账户管理") }}</h2><div class="uf-row"><span>{{ $t("原 UID") }}</span><b>{{legacy.id}}</b></div><div class="uf-row"><span>{{ $t("原等级") }}</span><b>{{legacy.level||'—'}}</b></div><div class="uf-row"><span>{{ $t("原上级 UID") }}</span><b>{{legacy.parent_id||'—'}}</b></div><div class="uf-row"><span>{{ $t("原总额度") }}</span><b>{{legacy.quota?.total_quota||'—'}}</b></div><div class="uf-row"><span>{{ $t("原已用额度") }}</span><b>{{legacy.quota?.used_quota||'—'}}</b></div></article>
          <article class="uf-card"><h2>{{ $t("历史明细") }}</h2><nav class="uf-history-nav"><a v-for="item in historySections" :key="item.key" :class="{active:legacySection===item.key}" :href="historyUrl(item.key)">{{ $t(item.label) }}</a></nav><div v-if="legacySection==='overview'"><h3>{{ $t("原资产") }}</h3><p v-if="!legacy.balances?.length">{{ $t("原资料未记录独立余额明细。") }}</p><div v-for="(balance,index) in legacy.balances" :key="index" class="uf-row"><span>{{balance.asset_symbol}} {{ $t("可用 / 冻结") }}</span><b>{{balance.available_amount}} / {{balance.frozen_amount}}</b></div><h3>{{ $t("累计收益") }}</h3><div v-for="(amount,key) in legacy.cumulative" :key="key" class="uf-row"><span>{{ $t(historyLabel(key)) }}</span><b>{{amount}}</b></div></div><div v-else-if="legacySection==='team'"><div class="uf-row"><span>{{ $t("原直属 / 原团队") }}</span><b>{{legacy.performance?.direct_invite_count??'—'}} / {{legacy.performance?.total_team_count??'—'}}</b></div><div class="uf-row"><span>{{ $t("原团队业绩 / 小区业绩") }}</span><b>{{legacy.performance?.team_performance??'—'}} / {{legacy.performance?.small_area_performance??'—'}}</b></div><div v-for="person in legacy.team?.rows||[]" :key="person.id" class="uf-record"><b>{{ $t("原 UID") }} {{person.id}}</b><small>{{ $t("第") }} {{person.depth}} {{ $t("层 · 原等级") }} {{person.level||'—'}}</small></div><div class="uf-history-pages"><a v-if="legacy.team?.page>1" :href="historyUrl('team',legacy.team.page-1)">{{ $t("上一页") }}</a><span>{{legacy.team?.page||1}} / {{legacy.team?.last_page||1}}</span><a v-if="legacy.team?.page<legacy.team?.last_page" :href="historyUrl('team',legacy.team.page+1)">{{ $t("下一页") }}</a></div></div><div v-else-if="legacySection==='treasury'"><div v-for="(value,key) in legacy.reserve" :key="key" class="uf-row"><span>{{ $t(historyLabel(key)) }}</span><b>{{value}}</b></div></div><div v-else-if="legacySection==='bao'||legacySection==='vip'"><p>{{ $t("账户权益及订单记录。") }}</p><div v-for="(value,key) in legacy.summary" :key="key" class="uf-row"><span>{{key}}</span><b>{{value}}</b></div></div><div v-else><p v-if="!legacy.history?.rows?.length">{{ $t("暂无已保存的记录。") }}</p><div v-for="(row,index) in legacy.history?.rows||[]" :key="index" class="uf-record"><b>{{row.burn_type_name||row.type_name||$t('历史记录')}} · {{row.burn_amount||row.amount||'—'}}</b><small>{{row.created_at||'—'}}</small></div><div class="uf-history-pages"><a v-if="legacy.history?.page>1" :href="historyUrl(legacySection,legacy.history.page-1)">{{ $t("上一页") }}</a><span>{{legacy.history?.page||1}} / {{legacy.history?.last_page||1}}</span><a v-if="legacy.history?.page<legacy.history?.last_page" :href="historyUrl(legacySection,legacy.history.page+1)">{{ $t("下一页") }}</a></div></div></article>
        </template>
        <article v-if="businessHistory" class="uf-card"><h2>{{ $t("UMI 账户 ·") }} {{businessHistory.code}}</h2><div v-for="b in businessHistory.balances" :key="b.pocket+b.asset" class="uf-row"><span>{{ $t(historyPocket(b.pocket)) }} · {{b.asset}}</span><b>{{fmt(b.amount)}}</b></div><h3>{{ $t("账务明细") }}</h3><div v-for="e in businessHistory.entries" :key="e.id" class="uf-record"><div><b>{{e.description}}</b><span>{{fmt(e.delta)}} {{e.asset}}</span></div><small>{{date(e.created_at)}} {{ $t("· 余额") }} {{fmt(e.balance_after)}}</small></div><div class="uf-history-pages"><a v-if="businessHistory.entry_pagination?.prev" :href="businessHistory.entry_pagination.prev">{{ $t("上一页") }}</a><span>{{ $t("共") }} {{businessHistory.entry_pagination?.total}} {{ $t("条") }}</span><a v-if="businessHistory.entry_pagination?.next" :href="businessHistory.entry_pagination.next">{{ $t("下一页") }}</a></div></article>
      </section>
    <umi-records v-if="data.member && tab==='records'"/><template v-if="data.member">
      <section v-if="tab==='mine'" class="uf-mine">
        <div class="uf-quick-actions"><button @click="selectTab('join')">↙ {{ $t('充值 UMI') }}</button><Link :href="handoff('/market/UMI-USDT')">⇄ {{ $t('交易') }}</Link><button @click="selectTab('withdraw')">↗ {{ $t('提取') }}</button></div>
        <article class="uf-card uf-pockets"><h2>{{ $t('收益划转') }}</h2><div v-for="kind in ['static','team','referral']" :key="kind" class="uf-pocket"><button class="uf-pocket-name" @click="selectTab('income',kind)"><img :src="'/umi/v2/art/income-'+kind+'.png'" alt=""><span><b>{{ $t(pocket(kind)) }}</b><small>{{fmt(income[kind+'_pending'])}} UMI</small></span></button><button class="uf-outline" @click="openIncomeTransfer(kind)">+ {{ $t('划转') }}</button></div></article>
        <article class="uf-card uf-shortcuts"><button @click="selectTab('income')">↗ {{ $t('我的收益') }}</button><button @click="selectTab('team')">♧ {{ $t('我的团队') }}</button><button @click="selectTab('points')">◇ {{ $t('股票积分') }}</button><button @click="selectTab('history')">◷ {{ $t('历史记录') }}</button></article>
        <details class="uf-card uf-balances"><summary>{{ $t('账户明细') }}</summary><div class="uf-row"><span>{{ $t('现货可用') }}</span><b>{{data.wallet_available?fmt(data.wallet_umi):'—'}} UMI</b></div><div class="uf-row"><span>{{ $t('待激活本金') }}</span><b>{{fmt(data.pending_principal_umi)}} UMI</b></div><div class="uf-row"><span>{{ $t('提取中') }}</span><b>{{fmt(income.withdrawal_reserved)}} UMI</b></div><p v-if="data.account_merge">{{ $t('原账户本金已接续，凭证 #') }}{{data.account_merge.id}}</p></details>
      </section>
    </template>
    <div class="uf-refresh"><button :disabled="busy||refreshing" @click="refreshState">{{refreshing?$t('正在刷新…'):$t('刷新账户状态')}}</button><small v-if="lastRefreshed">{{lastRefreshed}}</small></div><p v-if="message" class="uf-feedback" role="status">{{ $t(message) }}</p><p v-if="error" class="uf-error" role="alert">{{ $t(error) }}</p>
  </main>
  <nav v-if="data.member" class="uf-mobile-nav" :aria-label="$t(&quot;UMI 导航&quot;)"><button v-for="item in mobileTabs" :key="item.key" :class="{active:tab===item.key || (item.key==='mine' && secondaryPage)}" @click="selectTab(item.key)"><span>{{ item.icon }}</span>{{ $t(item.label) }}</button></nav>
</app-layout>
</template>

<script>
import UmiIncome from '@/Components/UmiIncome';
import {copyText} from '@/Functions/Clipboard.mjs';
import UmiLocale from '@/Functions/UmiLocale';
import AppLayout from '@/Layouts/AppLayout';

import axios from 'axios';
import QrCode from 'vue-qrcode-component';
import UmiRecords from '@/Components/UmiRecords';
import UmiTeamOverview from '@/Components/UmiTeamOverview';
import {formatUmi,umiTime,umiStatus,positiveUmi,validUmiAmount} from '@/Functions/UmiDisplay';
import {prepareIntent, retainIntentAfterError, validShareAmount} from '@/Functions/UmiRequest';
export default {mixins:[UmiLocale], components:{UmiIncome,AppLayout,UmiRecords,UmiTeamOverview,QrCode}, props:{state:{type:Object,required:true},legacy:{type:Object,default:null},legacySection:{type:String,default:'overview'},businessHistory:{type:Object,default:null}}, data(){return {data:this.state,refreshing:false,stateVersion:0,lastRefreshed:null,refreshTimer:null,quoteTimer:null,quoteLoading:false,tab:new URLSearchParams(window.location.search).get('tab') || 'home',busy:false,error:'',message:'',pendingIntent:null,stockConfirm:false,sponsorCode:(new URLSearchParams(window.location.search).get('umi_invite')||'').slice(0,40),joinAmount:'',joinPreview:null,transferCycle:'',transferPocket:'static',transferAmount:'',withdrawAmount:'',withdrawPreview:null,stockAmount:'',legacyIdentifier:'',legacyChallenge:'',legacyCode:'',historySections:[{key:'overview',label:this.$t("总览")},{key:'burn',label:this.$t("燃烧与额度")},{key:'team-income',label:this.$t("团队收益")},{key:'usdt',label:this.$t("USDT 流水")},{key:'team-usdt',label:this.$t("团队 USDT")},{key:'team',label:this.$t("原团队")},{key:'treasury',label:this.$t("储备金")},{key:'bao',label:this.$t("UMI 宝")},{key:'vip',label:this.$t("VIP 质押")}],tabs:[{key:'home',label:this.$t("首页"),icon:'⌂'},{key:'join',label:this.$t("充值"),icon:'◈'},{key:'income',label:this.$t("收益"),icon:'↗'},{key:'team',label:this.$t("团队"),icon:'♧'},{key:'withdraw',label:this.$t("提现"),icon:'⇄'},{key:'burn',label:this.$t("销毁"),icon:'◌'},{key:'points',label:this.$t("积分"),icon:'◇'},{key:'records',label:this.$t("完整记录"),icon:'◫'},{key:'history',label:this.$t("原账户档案"),icon:'◫'},{key:'mine',label:this.$t("我的"),icon:'●'}]};},mounted(){this.refreshQuote();this.quoteTimer=setInterval(()=>{if(!document.hidden && ['home','join'].includes(this.tab))this.refreshQuote();},10000);this.refreshTimer=setInterval(()=>{if(!document.hidden && ((this.data.lots||[]).some(l=>['pending','custody'].includes(l.status)) || (this.data.withdrawals||[]).some(w=>w.status==='awaiting_topup')))this.refreshState();},15000);},beforeUnmount(){clearInterval(this.refreshTimer);clearInterval(this.quoteTimer);},beforeDestroy(){clearInterval(this.refreshTimer);clearInterval(this.quoteTimer);}, computed:{incomeKind(){const kind=new URL(this.$page.url,window.location.origin).searchParams.get('income_kind');return ['static','team','referral'].includes(kind)?kind:''},secondaryPage(){return !['home','join','mine'].includes(this.tab)},pageTitle(){return this.$t(({home:'生态首页',join:'充值 UMI',mine:'我的 UMI',income:'我的收益',team:'我的团队',transfer:'收益划转',progress:'提取进度',withdraw:'提取到 Deepro',burn:'销毁明细',points:'股票积分',records:'业务记录',history:'账户资料'})[this.tab]||'UMI')},inviteUrl(){return window.location.origin+'/umi-ecosystem/portfolio?umi_invite='+encodeURIComponent(this.data.member?.member_code||'');},stockBalance(){return this.data.stock_balance_shares;},transferableCycles(){return this.data.cycles.filter(c=>positiveUmi(c.transferable?.[this.transferPocket]));},transferMaximum(){return this.data.cycles.find(c=>String(c.id)===String(this.transferCycle))?.transferable?.[this.transferPocket]||'0';},validTransfer(){return validUmiAmount(this.transferAmount,this.transferMaximum);},mobileTabs(){return this.tabs.filter(x=>['home','join','mine'].includes(x.key));},pointBalance(){return this.data.pending_points || '0';},validStockAmount(){return validShareAmount(this.stockAmount,this.data.stock_trading_wallet?.maximum || '0');},income(){return this.data.income||{available:'0',static_pending:'0',team_pending:'0',referral_pending:'0'};}}, watch:{transferPocket(){this.transferCycle='';this.transferAmount='';},transferCycle(){this.transferAmount='';}, '$page.url'(url){const key=new URL(url,window.location.origin).searchParams.get('tab')||'home';this.tab=key;this.message='';},state(next){this.data=next;}}, methods:{async refreshQuote(){if(this.quoteLoading)return;this.quoteLoading=true;try{const r=await axios.get('/umi-ecosystem/portfolio/quote');this.$set(this.data,'spot_quote',r.data);}catch(_){this.$set(this.data,'spot_quote',{available:false});}finally{this.quoteLoading=false;}},handoff(url){const target=new URL(url,window.location.origin);target.searchParams.set('from','umi');target.searchParams.set('umi_tab',this.tab);return target.pathname+target.search;},async refreshState(){if(this.busy||this.refreshing)return;this.refreshing=true;const version=this.stateVersion;try{const r=await axios.get('/umi-ecosystem/portfolio',{params:{state_only:1}});if(version!==this.stateVersion||this.busy)return;this.data=r.data.state;this.lastRefreshed=new Date().toLocaleTimeString();}catch(e){this.error=e.response?.data?.message||this.$t('刷新失败，已保留当前记录。');}finally{this.refreshing=false;}},selectTab(key,kind=''){if(this.busy||this.pendingIntent){this.error=this.$t('请先确认当前操作结果后再切换页面。');return;}if(key===this.tab&&kind===this.incomeKind)return;this.$inertia.visit('/umi-ecosystem/portfolio?tab='+encodeURIComponent(key)+(kind?'&income_kind='+encodeURIComponent(kind):''),{preserveState:true,preserveScroll:false,onSuccess:()=>{this.tab=key;this.message='';}});},openIncomeTransfer(kind){if(kind)this.transferPocket=kind;this.selectTab('transfer');},fmt:formatUmi,date(value){return umiTime(value,this.$i18n.locale);},statusLabel(value){return this.$t(umiStatus(value));},positive:positiveUmi,async copyInvite(value){try{await copyText(value,this.$el);this.message=this.$t('已复制。');}catch(e){this.error=this.$t('暂时无法自动复制，请长按下方链接复制。');}},recordUrl(dataset,withdrawalId){return '/umi-ecosystem/portfolio?tab=records&record_dataset='+dataset+(withdrawalId?'&record_withdrawal='+withdrawalId:'');},key(){return 'ui-'+Date.now()+'-'+Math.random().toString(36).slice(2,10);},stockStatus(s){return {points_only:this.$t('待确权'),locked:this.$t('已确权 · 锁定中'),tradable:this.$t('可划转')}[s]||this.$t('待处理');},historyUrl(section,page=1){return '/umi-ecosystem/portfolio?tab=history&legacy_section='+encodeURIComponent(section)+'&page='+page;},historyPocket(v){return {main:this.$t('可用余额'),linear:this.$t('理财收益'),team:this.$t('团队收益'),referral:this.$t('推荐收益'),treasure:this.$t('UMI 宝'),reserve:this.$t('储备金'),vip:this.$t('质押'),unstaking:this.$t('解锁中'),points:this.$t('股票积分')}[v]||v;},historyLabel(key){return {linear_release_cumulative_umi:this.$t('累计理财收益'),team_cumulative_umi:this.$t('累计团队收益'),referral_cumulative_umi:this.$t('累计推荐收益'),total_earnings_cumulative_umi:this.$t('累计总收益'),burn_umi_balance:this.$t('燃烧储备金 UMI'),burn_usdt_balance:this.$t('燃烧储备金 USDT')}[key]||key;},async startLegacyBinding(){this.error='';this.busy=true;try{const r=await axios.post('/umi-ecosystem/bind/code',{identifier:this.legacyIdentifier});this.legacyChallenge=r.data.challenge;this.message=r.data.message;}catch(e){this.error=e.response?.data?.message||this.$t('暂时无法发送验证码。');}finally{this.busy=false;}},async completeLegacyBinding(){this.error='';this.busy=true;try{await axios.post('/umi-ecosystem/bind/complete',{challenge:this.legacyChallenge,code:this.legacyCode});window.location.href='/umi-ecosystem/portfolio?tab=history';}catch(e){this.error=Object.values(e.response?.data?.errors||{}).flat().join('；')||e.response?.data?.message||this.$t('验证未完成，请核对验证码。');}finally{this.busy=false;}},stockMove(s){return {entitlement:this.$t('确权'),unlock:this.$t('解锁'),transfer:this.$t('站内划转'),write_off:this.$t('核销'),exchange_transfer:this.$t('转入 Deepro')}[s]||s;},cycleStatus(s){return {cancelled:this.$t('已退回'),active:this.$t('释放中'),pending_burn:this.$t('等待销毁确认'),completed:this.$t('已完成')}[s]||this.$t('处理中');},withdrawStatus(s){return {paid:this.$t('已到 Deepro 资金账户'),awaiting_topup:this.$t('等待补充 UMI'),funded:this.$t('处理中')}[s]||this.$t('处理中');},pocket(s){return {static:this.$t('理财收益'),team:this.$t('团队收益'),referral:this.$t('推荐收益')}[s]||this.$t('收益');},burnPurpose(s){return {activation:this.$t('充值销毁'),withdrawal:this.$t('提现销毁'),injury:this.$t('超额销毁')}[s]||this.$t('销毁');},async preview(action,amount,target){this.error='';this.busy=true;try{const r=await axios.post('/umi-ecosystem/portfolio/preview',{action,amount});this[target]=r.data;}catch(e){this[target]=null;this.error=e.response?.data?.message||this.$t('暂时无法计算，请核对数量。');}finally{this.busy=false;}},async submit(action,fields={}){this.stateVersion++;this.error='';this.message='';this.busy=true;fields={sponsor_code:this.sponsorCode,...fields};this.pendingIntent=prepareIntent(this.pendingIntent,action,fields,()=>this.key());try{const r=await axios.post('/umi-ecosystem/portfolio',{action,request_key:this.pendingIntent.key,...fields});this.data=r.data.state;this.pendingIntent=null;this.joinPreview=null;this.withdrawPreview=null;if(action==='stock_to_deepro'){this.stockAmount='';this.stockConfirm=false;}if(action==='transfer'){this.transferAmount='';this.transferCycle='';}const receipt=r.data.result?.receipt||r.data.result;const id=receipt?.id?' #'+receipt.id:'';this.message=['withdraw','spot_topup'].includes(action)?this.$t('提取订单')+id+' · '+this.withdrawStatus(receipt.status):action==='activate'?this.$t('充值订单')+id+' · '+umiStatus(receipt.status):action==='stock_to_deepro'?this.$t('划转凭证')+id+this.$t('：份额已转入 Deepro HK08379 交易账户。'):action==='transfer'?this.$t('收益划转')+id+this.$t('已入账；可提余额 ')+formatUmi(receipt.available_after_umi)+' UMI。':this.$t('UMI 账户')+id+this.$t('已开通。');}catch(e){if(!retainIntentAfterError(e))this.pendingIntent=null;this.error=Object.values(e.response?.data?.errors||{}).flat().join('；')||e.response?.data?.message||this.$t('操作未完成，请稍后重试。');}finally{this.busy=false;}if(!this.error && ['withdraw','spot_topup'].includes(action))this.selectTab('progress');}} };
</script>

